SELECT ?investorId (COUNT(?portfolioHealthId) AS ?hasPortfolioHealth) (COUNT(?holdingId) AS ?hasHolding)
WHERE {
  ?investor rdf:type wm:Investor .
  ?investor wm:investorId ?investorId .
  FILTER NOT EXISTS {
    ?investor wm:hasRiskTolerance ?riskTolerance .
  }
  OPTIONAL {
    ?portfolioHealth rdf:type wm:PortfolioHealth .
    ?portfolioHealth wm:healthOfInvestor ?investor .
    ?portfolioHealth wm:portfolioHealthId ?portfolioHealthId .
  }
  OPTIONAL {
    ?portfolioHolding rdf:type wm:PortfolioHolding .
    ?portfolioHolding wm:heldByInvestor ?investor .
    ?portfolioHolding wm:holdingId ?holdingId .
  }
}
