SELECT ?holdingId
WHERE {
  ?holding rdf:type wm:PortfolioHolding .
  ?holding wm:holdingId ?holdingId .
  FILTER NOT EXISTS { ?holding wm:investmentType ?investmentType . FILTER(STR(?investmentType) = "" || !BOUND(?investmentType)) }
  FILTER NOT EXISTS { ?holding wm:sector ?sector . FILTER(STR(?sector) = "" || !BOUND(?sector)) }
  FILTER NOT EXISTS { ?holding wm:segment ?segment . FILTER(STR(?segment) = "" || !BOUND(?segment)) }
