PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorName ?combined_score
WHERE {
  ?investor rdf:type wm:Investor .
  ?investor wm:investorName ?investorName .

  {
    SELECT ?cashFlowAmount
    WHERE {
      ?cashFlow rdf:type wm:CashFlow .
      ?cashFlow wm:cashFlowOfInvestor ?investor .
      ?cashFlow wm:amount ?cashFlowAmount .
    }
  }

  {
    SELECT ?rebalancingAmount
    WHERE {
      ?rebalancingAction rdf:type wm:RebalancingAction .
      ?rebalancingAction wm:rebalancingActionOfInvestor ?investor .
      ?rebalancingAction wm:amount ?rebalancingAmount .
    }
  }

  {
    SELECT ?scenarioAllocationChange
    WHERE {
      ?scenarioRebalancing rdf:type wm:ScenarioRebalancing .
      ?scenarioRebalancing wm:scenarioRebalancingOfInvestor ?investor .
      ?scenarioRebalancing wm:newAllocationPct ?scenarioAllocationChange .
    }
  }

  BIND (xsd:decimal(SUM(?cashFlowAmount)) + xsd:decimal(SUM(?rebalancingAmount)) + xsd:decimal(SUM(?scenarioAllocationChange)) AS ?combined_score)
}
GROUP BY ?investorName
ORDER BY DESC(?combined_score) ?investorName
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?segment (AVG(xsd:decimal(?rebalancing_amount)) AS ?rebalancing_amount) (AVG(xsd:decimal(?cash_flow)) AS ?cash_flow) (AVG(xsd:decimal(?transaction_count)) AS ?transaction_count)
WHERE {
  ?investor rdf:type wm:Investor .
  ?investor wm:hasSegment ?segment .
  {
    ?investor wm:hasRebalancingAction ?rebalancingAction .
    ?rebalancingAction wm:amount ?rebalancing_amount .
  }
  {
    ?investor wm:hasCashFlow ?cashFlow .
    ?cashFlow wm:amount ?cash_flow .
  }
  {
    ?investor wm:hasRebalancingAction ?rebalancingAction2 .
    ?rebalancingAction2 wm:rebalanceId ?transaction_count .
  }
}
GROUP BY ?segment
